  getPhaseStateTool,
  getDecisionsTool,
  getExitCriteriaTool,
  advancePhaseTool,
  startIterationTool,
  recordDecisionTool,
  recordActivatedLensesTool,
  updateScoreTool,
  markExitCriterionTool,
  checkSafeguardTool,
  checkAllSafeguardsTool,
  checkSpecsStatusTool,
  initProjectTool,
  getPhaseGuidanceTool,
  updateProjectSpecTool,
  startNewCycleTool
