// src/mcp/server.ts
function getWorkspacePath() {
  const args = process.argv.slice(2);
  const wsIndex = args.indexOf("--workspace");
  if (wsIndex !== -1 && args[wsIndex + 1]) {
    return args[wsIndex + 1];
  }
  if (process.env.CLAUDE_PROJECT_DIR) {
    return process.env.CLAUDE_PROJECT_DIR;
  }
  if (process.env.VERSUS_WORKSPACE) {
    return process.env.VERSUS_WORKSPACE;
  }
  return process.cwd();
}
async function main() {
  const workspacePath = getWorkspacePath();
  const engine = new StateEngine(workspacePath);
  engine.load();
  const server = new Server(
    {
      name: "versus-claude",
      version: "0.14.2"
    },
    {
      capabilities: {
        tools: {}
      }
    }
  );
  server.setRequestHandler(ListToolsRequestSchema, async () => {
    return { tools: ALL_TOOLS };
  });
  server.setRequestHandler(CallToolRequestSchema, async (request) => {
    const { name, arguments: args } = request.params;
    try {
      engine.load();
      const result = handleToolCall(name, args ?? {}, engine);
      return {
        content: [{ type: "text", text: result }]
      };
    } catch (err) {
      return {
        content: [
          {
            type: "text",
            text: JSON.stringify({ error: `Internal error: ${String(err)}` })
          }
        ],
        isError: true
      };
    }
  });
  const transport = new StdioServerTransport();
  await server.connect(transport);
}
main().catch((err) => {
  process.stderr.write(`Versus MCP Server fatal: ${String(err)}
`);
  process.exit(1);
});
